import{z as l,x as n,o as E,c as A,q as s,j as r,D as a,d as i,s as t,S as d}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"链接器的深入","description":"","frontmatter":{"title":"链接器的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-linker-deep.md","filePath":"cs/cg-linker-deep.md","lastUpdated":1791063341000}'),B={name:"cs/cg-linker-deep.md"};function c(p,e,h,m,_,T){const o=n("Mermaid");return E(),A("div",null,[e[2]||(e[2]=s('<h1 id="链接器的深入" tabindex="-1">链接器的深入 <a class="header-anchor" href="#链接器的深入" aria-label="Permalink to &quot;链接器的深入&quot;">​</a></h1><div class="epigraph"><p>链接器是最后一个看到全程序的人：地址在它手里才定下来，所以最后一遍优化也归它管。</p><footer>—— 据 Levine, *Linkers and Loaders*；Drepper, *How to Write Shared Libraries*, 2006 整理</footer></div><p><a href="/cs/cg-simd-autovec">上一课</a>的向量循环编译成目标文件之后，谁来把它们装订成一个程序？<a href="/cs/linker-symbol-resolution">符号解析</a>、<a href="/cs/linker-script-sections">链接脚本</a>与<a href="/cs/relocation-types">重定位类型</a>给过机制。本课换一个视角，把链接器当优化器看：地址定下来之后才可能做的那批 pass——可达性回收、等价折叠、寻址松弛、布局——以及它如何变成优化器的入口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>符号解析是约束求解，不是查表。归档语义已经预设了求解次序：GNU ld 从左到右扫归档，只取能满足当前未定义引用的成员；左边的成员引用右边的成员能解析，反过来不行——循环依赖的归档要靠重复扫描到不动点。顺序敏感不是实现偷懒，是语义如此。第二类问题更隐蔽：编译器做优化时地址是假的，有些优化因此做不了——「这个跳转其实够得着，不必走寄存器间接」要等最终地址定了才知道。谁看得见最终地址，谁就欠这一遍优化。</p><p><span class="marginnote">术语翻译：归档（.a 文件）就是「一捆目标文件的压缩包」，链接器默认不整个打开，而是按需抽出能补上当前缺口的那几个成员；重定位则是目标文件里的「补丁清单」——每个条目写着「某地址处留了空，装载时按这种公式填入真值」。</span></p><h3 id="链接期的四个-pass" tabindex="-1">链接期的四个 pass <a class="header-anchor" href="#链接期的四个-pass" aria-label="Permalink to &quot;链接期的四个 pass&quot;">​</a></h3><p>可达性回收：<code>--gc-sections</code> 从入口沿引用可达的节保留，其余丢弃；脚本里的 <code>KEEP()</code> 钉住不许丢的节，异常表与初始化函数数组是最常见的钉点。等价折叠（ICF）：内容相同的函数合并为一个，<a href="/cs/icf-identical-code-folding">函数指针的身份</a>是合法性边界。寻址松弛：布局定址后，把远距离寻址序列改写成短形式——RISC-V 上 <code>AUIPC+JALR</code> 对换成一条 <code>JAL</code>，地址范围证明了短形式够用。布局：函数与数据的次序影响 i-cache、i-TLB 与页共享，排序选项与 map 文件把布局变成可审查、可复现的决定。</p><p><span class="marginnote">归档顺序错误是链接器最古老的坑：报的错（未定义引用）与真实原因（成员被跳过）隔着一层语义。<code>--start-group</code> 用重复扫描换正确性，代价是链接时间；<code>--as-needed</code> 顺手把没被真正用到的动态依赖从输出里剪掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LTO 把链接器变成优化器的入口：编译器把 IR 而不只是机器码放进目标文件，链接期由插件把全程序 IR 打开，中端跨模块重新跑一轮，再回到后端重新生成。内联跨过模块边界、常量跨过文件边界传播，「全程序才能做」的优化终于有了位置。链接器本身从装配工变成「装配工 + 优化调度器」：它决定哪些代码重新进后端，以及重新生成之后怎么放。</p><p><span class="marginnote">直觉类比：不开 LTO 时，每个 .c 文件像各自打包的散件，装配工只能按图纸把它们拼起来；开了 LTO，等于把所有散件拆回「半成品图纸」（IR）重新看一遍全局——哪些零件能互相嵌进去（跨文件内联）、哪些根本没人用（可达性回收），这下才看得见。</span></p>',12)),(E(),r(d,null,{default:a(()=>[t(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJS%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%20%2F%20%E5%BD%92%E6%A1%A3%22%5D%20--%3E%20RES%5B%22%E7%AC%A6%E5%8F%B7%E8%A7%A3%E6%9E%90%EF%BC%9A%E7%BA%A6%E6%9D%9F%E6%B1%82%E8%A7%A3%22%5D%0A%20%20RES%20--%3E%20GC%5B%22%E5%8F%AF%E8%BE%BE%E6%80%A7%E5%9B%9E%E6%94%B6%20gc-sections%22%5D%0A%20%20GC%20--%3E%20ICF%5B%22%E7%AD%89%E4%BB%B7%E6%8A%98%E5%8F%A0%20ICF%22%5D%0A%20%20ICF%20--%3E%20LAY%5B%22%E5%B8%83%E5%B1%80%E5%AE%9A%E5%9D%80%22%5D%0A%20%20LAY%20--%3E%20RELAX%5B%22%E5%AF%BB%E5%9D%80%E6%9D%BE%E5%BC%9B%E6%94%B9%E5%86%99%22%5D%0A%20%20RELAX%20--%3E%20OUT%5B%22%E6%AE%B5%20%2B%20%E9%87%8D%E5%AE%9A%E4%BD%8D%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>布局是松弛的前提，松弛又改布局的大小，所以两者迭代到不动点——短形式省下的字节可能让后面的函数挪进跳转范围，多省一段。与动态链接的合同同样在布局里：<a href="/cs/got-plt">GOT 与 PLT</a> 的间接层在符号不能就地绑定时才必要，<code>-Bsymbolic</code> 让内部引用就地解析，少付一层 PLT；<a href="/cs/symbol-interposition">符号插入</a>的默认规则（导出符号全局可插）正是换来<a href="/cs/load-dynlink">动态加载</a>灵活性的代价。可见性属性把默认合同收窄：<code>hidden</code> 告诉链接器这个符号不出共享库，间接层当场省掉。</p><p><span class="marginnote">数字实例：RISC-V 的远跳 <code>AUIPC+JALR</code> 是两条共 8 字节；布局定址后若目标在 <code>JAL</code> 的 \\(\\pm 1\\,\\text{MiB}\\) 范围内，松弛成一条 4 字节——省一半，还少占一个发射槽。整个库的函数互相挪近后，能这样折半的跳转成片出现。</span></p>',3)),(E(),r(d,null,{default:a(()=>[t(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E5%BA%93%E5%86%85%E8%B0%83%E7%94%A8%20f%22%5D%20--%3E%20VIS%7B%22f%20%E7%9A%84%E5%8F%AF%E8%A7%81%E6%80%A7%EF%BC%9F%22%7D%0A%20%20VIS%20--%3E%7C%22%E9%BB%98%E8%AE%A4%E5%AF%BC%E5%87%BA%22%7C%20PLT%5B%22%E7%BB%8F%20PLT%2FGOT%20%E9%97%B4%E6%8E%A5%E8%B7%B3%EF%BC%9A%E5%8F%AF%E8%A2%AB%E6%8F%92%E5%85%A5%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20VIS%20--%3E%7C%22hidden%22%7C%20DIR%5B%22%E5%B0%B1%E5%9C%B0%E7%BB%91%E5%AE%9A%EF%BC%9A%E7%9B%B4%E6%8E%A5%20call%22%5D%0A%20%20PLT%20--%3E%20COST%5B%22%E5%A4%9A%E4%B8%80%E8%B7%B3%E9%97%B4%E6%8E%A5%20%2B%20%E4%B8%80%E6%AC%A1%E5%86%85%E5%AD%98%E8%AF%BB%22%5D%0A%20%20DIR%20--%3E%20FAST%5B%22%E9%9B%B6%E9%97%B4%E6%8E%A5%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>重定位的计算与 ELF 结构各有先修课，本课不重推；运行时动态链接器（ld.so 的重绑定与懒绑定）是加载侧的事，本课停在链接期。LTO 打开之后的中端优化不属于本课——链接器只是把门打开；全程序优化的代价（内存、链接时间、调试信息一致性）按工程账另算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>符号解析是约束求解：归档语义决定次序敏感，循环依赖重复扫到不动点。</li><li>链接期四个 pass：可达回收、等价折叠、寻址松弛、布局，全部只有链接器做得成。</li><li>LTO 让链接器成为优化器入口：全程序 IR 在这里重新打开。</li><li>布局是性能与合同的交点：i-cache、PLT 与可见性都在次序里。</li><li>出处：Levine, <em>Linkers and Loaders</em>；Drepper, <em>How to Write Shared Libraries</em>, 2006；ELF / SysV ABI。</li></ul>',4))])}const L=l(B,[["render",c]]);export{f as __pageData,L as default};
